const item = $input.first();

// Buscar el archivo que haya llegado al Webhook
const campos = Object.keys(item.binary ?? {});

const campoImagen = campos.includes("Imagen")
  ? "Imagen"
  : campos.length === 1
    ? campos[0]
    : null;

const imagen = campoImagen
  ? item.binary[campoImagen]
  : null;

return [{
  json: {
    imagenRecibida: Boolean(imagen),
    campoBinario: campoImagen,
    archivo: imagen?.fileName ?? null,
    formato: imagen?.mimeType ?? null,
    mensaje: imagen
      ? "Imagen recibida correctamente"
      : "No se ha recibido ninguna imagen"
  },
  binary: item.binary
}];

const item = $input.first();

// Recuperar la fotografía recibida
const imagen = item.binary?.Imagen;

if (!imagen) {
  throw new Error("No se ha recibido ninguna imagen");
}

// Comprobar formato
const formatosPermitidos = [
  "image/jpeg",
  "image/png"
];

if (!formatosPermitidos.includes(imagen.mimeType)) {
  throw new Error("Formato no permitido. Usa JPG o PNG.");
}

// Recuperar los bytes de la imagen
const buffer = await this.helpers.getBinaryDataBuffer(
  0,
  "Imagen"
);

// Limitar a 8 MiB
if (buffer.length > 8 * 1024 * 1024) {
  throw new Error("La imagen supera el tamaño permitido");
}

// Convertir la imagen a Base64
const imagenBase64 = buffer.toString("base64");

return [{
  json: {
    ...item.json,
    imagenBase64,
    tamanoBytes: buffer.length,
    preparadaParaIA: true
  },
  binary: item.binary
}];

const respuesta = $input.first().json.message?.content;

// Recuperar la imagen original del nodo base64
const origen = $("base64").first();

if (!origen.binary?.Imagen) {
  throw new Error("No se encuentra la imagen original");
}

let documento;

try {
  if (typeof respuesta !== "string") {
    throw new Error("Respuesta vacía de Gemma");
  }

  const limpio = respuesta
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/, "")
    .trim();

  documento = JSON.parse(limpio);

  if (
    !documento ||
    typeof documento !== "object" ||
    Array.isArray(documento)
  ) {
    throw new Error("JSON incorrecto");
  }

} catch (error) {
  documento = {
    estado: "REVISION_MANUAL",
    tipo_documento: "INDETERMINADO",
    motivo: "No se pudo interpretar la respuesta de la IA"
  };
}


let tipoDocumento =
  documento.tipo_documento ?? "INDETERMINADO";

// Si la IA confirma que no existe documento visible,
// no conservamos un tipo documental inventado.
if (documento.documento_visible === false) {
  tipoDocumento = "OTRO";
} else if (documento.documento_visible !== true) {
  tipoDocumento = "INDETERMINADO";
}

// Tipos de documentos permitidos
const tiposAdmitidos = [
  "DNI_NIF",
  "TIE_NIE",
  "CERTIFICADO_NIE",
  "DOCUMENTO_NIF",
  "PASAPORTE"
];

// Comprobaciones visuales
const presentacionCorrecta =
  documento.documento_visible === true &&
  documento.documento_completo === true &&
  documento.mano_externa_visible === false &&
  documento.persona_externa_visible === false;

// Determinar si puede continuar
const documentoReconocido =
  documento.estado === "APTA" &&
  tiposAdmitidos.includes(tipoDocumento) &&
  presentacionCorrecta;

// Detectar incumplimientos claros
const incumplimiento =
  documento.documento_visible === false ||
  documento.documento_completo === false ||
  documento.mano_externa_visible === true ||
  documento.persona_externa_visible === true;

const estado = documentoReconocido
  ? "APTA"
  : (documento.estado === "NO_APTA" || incumplimiento)
    ? "NO_APTA"
    : "REVISION_MANUAL";

// Devolver únicamente los datos necesarios
return [{
  json: {
    estado,
    tipo_documento: tipoDocumento,
    documentoReconocido,
    presentacionCorrecta,
    motivo: estado === "APTA" || estado === documento.estado
      ? (documento.motivo ?? "Sin explicación")
      : "No se cumplen con seguridad las condiciones de presentación."
  },

  // Conservar la imagen para analizarla con Sharp después
  binary: origen.binary
}];

const sharp = require("sharp");

const item = $input.first();

// CONFIGURACIÓN
const TARGET_SIZE = 512;
const BLUR_THRESHOLD = 220;

// Comprobar que llega una imagen
if (!item.binary?.Imagen) {
  throw new Error("Sharp no recibió la imagen aprobada");
}

// Recuperar los bytes de la imagen actual
const buffer = await this.helpers.getBinaryDataBuffer(
  0,
  "Imagen"
);

// Obtener dimensiones originales
const metadata = await sharp(buffer).metadata();

// Normalizar a 512x512
const { data, info } = await sharp(buffer)
  .rotate()
  .resize(TARGET_SIZE, TARGET_SIZE, {
    fit: "fill",
    kernel: "cubic"
  })
  .toColourspace("srgb")
  .removeAlpha()
  .raw()
  .toBuffer({ resolveWithObject: true });

// Convertir a escala de grises
const gray = new Float32Array(
  TARGET_SIZE * TARGET_SIZE
);

for (let p = 0; p < gray.length; p++) {
  const i = p * info.channels;

  gray[p] =
    0.299 * data[i] +
    0.587 * data[i + 1] +
    0.114 * data[i + 2];
}

// Calcular varianza del Laplaciano
let sum = 0;
let sumSq = 0;
let n = 0;

for (let y = 1; y < TARGET_SIZE - 1; y++) {
  const row = y * TARGET_SIZE;

  for (let x = 1; x < TARGET_SIZE - 1; x++) {
    const i = row + x;

    const v =
      4 * gray[i] -
      gray[i - 1] -
      gray[i + 1] -
      gray[i - TARGET_SIZE] -
      gray[i + TARGET_SIZE];

    sum += v;
    sumSq += v * v;
    n++;
  }
}

const mean = n ? sum / n : 0;

const variance = n
  ? sumSq / n - mean * mean
  : 0;

// Clasificar nitidez
const borrosa = variance < BLUR_THRESHOLD;

return [{
  json: {
    ...item.json,
    valida: !borrosa,
    estadoNitidez: borrosa ? "BORROSA" : "NITIDA",
    varianza: Number(variance.toFixed(2)),
    umbral: BLUR_THRESHOLD,
    dimensionesOriginales:
      `${metadata.width}x${metadata.height}`,
    dimensionesAnalisis: "512x512",
    motivoNitidez: borrosa
      ? "La imagen no supera el umbral de nitidez."
      : "La imagen supera el umbral de nitidez."
  },
  binary: item.binary
}];

const datos = $input.first().json;

// Resultado de Gemma
const documentoOK =
  datos.estado === "APTA" &&
  datos.documentoReconocido === true &&
  datos.presentacionCorrecta === true;

// Resultado de Sharp
const nitidezOK =
  datos.valida === true &&
  datos.estadoNitidez === "NITIDA";

let estadoFinal;
let motivo;

if (datos.estado === "NO_APTA") {
  estadoFinal = "NO_APTA";
  motivo = datos.motivo || "Documento no admitido.";

  if (datos.valida === false) {
    motivo += " La imagen tampoco supera el control de nitidez.";
  }

} else if (datos.valida === false) {
  estadoFinal = "NO_APTA";
  motivo = datos.motivoNitidez ||
    "La fotografía está demasiado borrosa.";

} else if (documentoOK && nitidezOK) {
  estadoFinal = "APTA";
  motivo = "Documento reconocido, presentación correcta y nitidez suficiente.";

} else {
  estadoFinal = "REVISION_MANUAL";
  motivo = datos.motivo ||
    "No se pudo confirmar la validez de la imagen.";
}

// Respuesta final para React
return [{
  json: {
    apta: estadoFinal === "APTA",
    estado: estadoFinal,
    tipo_documento: datos.tipo_documento ?? "INDETERMINADO",
    nitidez: datos.estadoNitidez ?? "SIN_EVALUAR",
    varianza: datos.varianza ?? null,
    umbral: datos.umbral ?? null,
    requiere_nueva_foto: estadoFinal === "NO_APTA",
    requiere_revision_manual: estadoFinal === "REVISION_MANUAL",
    motivo
  }
}];
